const initialCustomers=[{id:1,name:'Priya Shah',email:'priya@example.invalid',phone:'+91 90000 00001',address:'24 Garden Road, Pune',initials:'PS'},{id:2,name:'Alex Morgan',email:'alex@example.invalid',phone:'+44 7700 900123',address:'18 Willow Lane, Bristol',initials:'AM'},{id:3,name:'Sam Rivera',email:'sam@example.invalid',phone:'+1 202 555 0148',address:'42 Oak Street, Austin',initials:'SR'},{id:4,name:'Taylor Chen',email:'taylor@example.invalid',phone:'+61 491 570 156',address:'9 Park Avenue, Sydney',initials:'TC'}];
