const line=(id,qty=1)=>({...catalog.find(x=>x.id===id),qty});
const seedJobs=()=>[{id:1042,title:'Water heater repair',customer:1,date:today,time:'09:00',window:'09:00–11:00',status:'In progress',priority:'Normal',staff:'You',notes:'Check the pressure valve. Customer will be home all morning.',items:[line('diagnostic'),line('filter',2)],estimate:'Approved',invoice:null,payments:[]},{id:1043,title:'Annual AC maintenance',customer:2,date:today,time:'11:30',window:'11:30–13:30',status:'Scheduled',priority:'Normal',staff:'Jamie',notes:'Service both indoor units.',items:[line('maintenance')],estimate:null,invoice:null,payments:[]},{id:1044,title:'Kitchen tap replacement',customer:3,date:today,time:'14:00',window:'14:00–16:00',status:'Scheduled',priority:'High',staff:'You',notes:'Bring the replacement seal.',items:[line('diagnostic'),line('seal')],estimate:'Sent',invoice:null,payments:[]},{id:1041,title:'Electrical safety check',customer:4,date:today,time:'08:00',window:'08:00–09:00',status:'Completed',priority:'Normal',staff:'Jamie',notes:'All checks complete.',items:[line('maintenance'),line('labor')],estimate:'Approved',invoice:'Paid',payments:[{amount:180,method:'Bank transfer',ref:'DEMO-1041',date:today}]},{id:1040,title:'Boiler inspection',customer:2,date:'2026-09-21',time:'10:00',window:'10:00–12:00',status:'Completed',priority:'Normal',staff:'You',notes:'Inspection completed.',items:[line('diagnostic'),line('labor')],estimate:'Approved',invoice:'Issued',payments:[]},{id:1045,title:'Garden pump service',customer:1,date:'2026-09-26',time:'10:00',window:'10:00–12:00',status:'Scheduled',priority:'Normal',staff:'You',notes:'Saturday visit.',items:[line('diagnostic')],estimate:null,invoice:null,payments:[]},{id:1046,title:'Appliance inspection',customer:3,date:'',time:'',window:'',status:'Draft',priority:'Normal',staff:'Unassigned',notes:'Call to arrange a visit.',items:[],estimate:null,invoice:null,payments:[]}];
let customers=structuredClone(initialCustomers),jobs=seedJobs(),currentId=1042,currency='USD',locale='en-US',route='overview',filter='All',query='',scheduleDay=today,draft=null,pickerSelection={},pickerFilter='All',pickerQuery='',pickerContext='job',customerContext='customers',lastFocus=null;
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog');
const money=value=>new Intl.NumberFormat(locale,{style:'currency',currency,maximumFractionDigits:2}).format(value);
const total=job=>job.items.reduce((sum,x)=>sum+x.price*x.qty,0);
const paid=job=>job.payments.reduce((sum,x)=>sum+x.amount,0);
const balance=job=>Math.max(0,total(job)-paid(job));
const customer=job=>customers.find(x=>x.id===job.customer)||customers[0];
const current=()=>jobs.find(x=>x.id===currentId)||jobs[0];
const dateLabel=value=>value?new Intl.DateTimeFormat(locale,{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):'Unscheduled';
const badge=status=>`<span class="badge ${({'In progress':'progress','Awaiting approval':'awaiting'}[status]||status||'Draft').toLowerCase()}">${esc(status||'Draft')}</span>`;
const button=(label,action,primary=false,ico='',extra='')=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const linkButton=(label,to,primary=false,ico='')=>`<a class="button ${primary?'primary':''}" href="#${to}">${ico?icon(ico):''}${label}</a>`;
const heading=(eyebrow,title,description,actions='')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;
const navItems=[['overview','Overview','grid'],['jobs','Jobs','jobs'],['schedule','Schedule','calendar'],['customers','Customers','users'],['estimates','Estimates','file'],['invoices','Invoices','money'],['catalog','Services & parts','box'],['reports','Reports','chart']];
function shell(){
 document.querySelector('#sidebar').innerHTML=`<a class="brand" href="#overview"><span class="brand-mark">s</span>ServiceDesk</a><div class="workspace-label"><span class="logo">${icon('tool')}</span><div><strong>Everyday Services</strong><small>Your workspace · Owner</small></div></div><p class="nav-group-label">Workspace</p><nav>${navItems.map(([id,title,i],n)=>`${n===4?'<p class="nav-group-label">Business</p>':''}<a class="nav-link ${activeNav(id)?'active':''}" href="#${id}" ${activeNav(id)?'aria-current="page"':''}>${icon(i)}${title}${id==='jobs'?`<span class="nav-count">${jobs.filter(j=>j.status!=='Completed').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><strong>A little less admin.</strong><p>One place for every job, from the first call to the final payment.</p><a href="#new-job">Create your next job →</a></div><a class="nav-link" href="#settings">${icon('settings')}Preferences</a><div class="account"><span class="avatar">AK</span><div><strong>Alex Kim</strong><small>Business owner</small></div></div></div>`;
 document.querySelector('.bottom-nav').innerHTML=[['overview','Home','grid'],['jobs','Jobs','jobs'],['new-job','New job','plus'],['schedule','Schedule','calendar']].map(([id,label,i])=>`<a href="#${id}" class="${id==='new-job'?'create ':''}${activeNav(id)?'active':''}" ${activeNav(id)?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')+`<button data-action="menu" aria-label="More navigation" aria-expanded="false">${icon('more')}More</button>`;
 document.querySelector('.mobile-menu').innerHTML=icon('menu');
 const label=({'new-job':'Create job',job:'Job details',estimate:'Estimate',invoice:'Invoice',approval:'Customer approval',settings:'Preferences'}[route]||navItems.find(x=>x[0]===route)?.[1]||'Overview');
 document.querySelector('#breadcrumb').innerHTML=`<span class="parent">Workspace</span><span class="parent">/</span><b>${label}</b>`;
}
function activeNav(id){return id===route||(id==='jobs'&&['job','new-job'].includes(route))||(id==='estimates'&&['estimate','approval'].includes(route))||(id==='invoices'&&route==='invoice')}
function stat(label,value,note,ico,emphasis=false){return `<article class="card stat ${emphasis?'emphasis':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><small>${note}</small>${label==="Today's jobs"?`<div class="mini-track"><i style="width:${Math.round(jobs.filter(j=>j.date===today&&j.status==='Completed').length/Math.max(1,jobs.filter(j=>j.date===today).length)*100)}%"></i></div>`:''}</article>`}
function agendaRow(j){const c=customer(j);return `<div class="agenda-row"><div class="agenda-time">${j.time||'—'}<small>${dateLabel(j.date)}</small></div><div class="agenda-info"><a class="job-title" href="#job/${j.id}">${esc(j.title)}</a><p>${esc(c.name)} · #J-${j.id}</p>${badge(j.status)}</div><div class="stack" style="gap:10px;justify-items:end"><span class="avatar-stack"><span class="person-dot">${j.staff==='You'?'AK':'JL'}</span>${j.staff}</span><a class="button small ${j.status==='In progress'?'soft':''}" href="#job/${j.id}">${j.status==='In progress'?'Continue':j.status==='Completed'?'View job':'Open job'}${icon('arrow')}</a></div></div>`}
function dashboard(){const todays=jobs.filter(j=>j.date===today);const completed=todays.filter(j=>j.status==='Completed').length;const unpaid=jobs.filter(j=>j.invoice&&j.invoice!=='Draft'&&balance(j)>0);const pending=jobs.filter(j=>j.estimate==='Sent');const revenue=jobs.reduce((s,j)=>s+paid(j),0);
 return heading('Tuesday, 22 September 2026','A good day to get things done.',`You have ${todays.filter(j=>j.status!=='Completed').length} visits to take care of today.`,linkButton('New job','new-job',true,'plus'))+`<section class="stats" aria-label="Business summary">${stat("Today's jobs",todays.length,`${completed} complete · ${todays.length-completed} to go`,'jobs')}${stat('Awaiting approval',pending.length,`${money(pending.reduce((s,j)=>s+total(j),0))} in estimates`,'file')}${stat('Unpaid invoices',money(unpaid.reduce((s,j)=>s+balance(j),0)),`${unpaid.length} invoice${unpaid.length!==1?'s':''} to follow up`,'money')}${stat('Collected this month',money(revenue),`Payments received · ${currency}`,'trend',true)}</section><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Your day, at a glance</h2><p>Tuesday’s visits · Workspace local time</p></div><a class="text-link" href="#schedule">Schedule ${icon('arrow')}</a></div><div class="day-label"><i class="live-dot"></i> ${todays.length} jobs · ${completed} completed</div>${todays.sort((a,b)=>a.time.localeCompare(b.time)).map(agendaRow).join('')}<div class="card-foot"><a class="text-link" href="#jobs">View all jobs ${icon('arrow')}</a></div></section><div class="stack"><section class="card"><div class="card-head"><h2>Needs your attention</h2><span class="badge awaiting">${pending.length+unpaid.length} open</span></div><div class="attention-row"><span class="attention-icon">${icon('file')}</span><div><h3>${pending.length} estimate awaiting approval</h3><p>Keep your upcoming work moving.</p><a class="text-link" href="#estimates">Review estimates ${icon('arrow')}</a></div></div><div class="attention-row"><span class="attention-icon blue">${icon('money')}</span><div><h3>${money(unpaid.reduce((s,j)=>s+balance(j),0))} still to collect</h3><p>See open balances and payment history.</p><a class="text-link" href="#invoices">Review invoices ${icon('arrow')}</a></div></div></section><section class="card"><div class="card-head"><h2>Recent activity</h2><a class="text-link" href="#reports">View reports</a></div><div class="activity"><div class="activity-row"><i class="activity-dot"></i><div>Payment received <b>${money(180)}</b><p>Electrical safety check · Bank transfer</p></div></div><div class="activity-row"><i class="activity-dot"></i><div>Estimate approved<p>Water heater repair · Priya Shah</p></div></div><div class="activity-row"><i class="activity-dot"></i><div>New job scheduled<p>Annual AC maintenance · 11:30 today</p></div></div></div></section><div class="welcome-note">${icon('check')}Your next step is always on the job page.</div></div></div>`;
}
function filteredJobs(){return jobs.filter(j=>(filter==='All'||j.status===filter)&&`${j.title} ${customer(j).name} J-${j.id}`.toLowerCase().includes(query.toLowerCase()))}
function jobRows(rows,mode='jobs'){if(!rows.length)return `<div class="empty-state">${icon('search')}<h2>No ${mode} found</h2><p>Try another name or reset your filters.</p>${button('Clear filters','clear-filter',false,'search')}</div>`;return `<div class="card job-table-wrap"><table class="job-table"><thead><tr><th>${mode==='jobs'?'Job':'Document'}</th><th>Customer</th><th>${mode==='jobs'?'Scheduled':'Date'}</th><th>Status</th><th class="amount">${mode==='invoices'?'Balance':'Total'}</th><th aria-label="Open"></th></tr></thead><tbody>${rows.map(j=>{const status=mode==='jobs'?j.status:mode==='estimates'?j.estimate:j.invoice;const dest=mode==='jobs'?'job':mode==='estimates'?'estimate':'invoice';const num=mode==='jobs'?'J':mode==='estimates'?'EST':'INV';return `<tr><td><span class="ref">#${num}-${j.id}</span><a class="job-title" href="#${dest}/${j.id}">${esc(j.title)}</a></td><td>${esc(customer(j).name)}<small>${esc(customer(j).address.split(',').pop().trim())}</small></td><td>${dateLabel(j.date)}<small>${esc(j.window||'Arrange a time')}</small></td><td>${badge(status)}</td><td class="amount">${money(mode==='invoices'?balance(j):total(j))}</td><td class="row-action"><a href="#${dest}/${j.id}" aria-label="Open ${esc(j.title)}">${icon('chevron')}</a></td></tr>`}).join('')}</tbody></table></div><div class="mobile-jobs">${rows.map(j=>{const dest=mode==='jobs'?'job':mode==='estimates'?'estimate':'invoice';return `<a class="card mobile-job" href="#${dest}/${j.id}"><div class="mobile-job-top"><span class="ref">#${mode==='jobs'?'J':mode==='estimates'?'EST':'INV'}-${j.id}</span>${badge(mode==='jobs'?j.status:mode==='estimates'?j.estimate:j.invoice)}</div><h3>${esc(j.title)}</h3><p>${esc(customer(j).name)}</p><div class="mobile-job-bottom"><span>${icon('calendar')}${dateLabel(j.date)} · ${j.time||'Arrange time'}</span><b>${money(mode==='invoices'?balance(j):total(j))}</b></div></a>`}).join('')}</div><div class="list-footer"><span>${rows.length} ${mode} shown</span><span>Sample workspace</span></div>`}
function jobsPage(){return heading('Your work','Jobs','A clear next step for every service visit.',linkButton('New job','new-job',true,'plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input data-input="job-search" aria-label="Search jobs" placeholder="Search jobs or customers…" value="${esc(query)}"></label><div class="filters" aria-label="Job status">${['All','Draft','Scheduled','In progress','Completed'].map(s=>`<button class="chip ${filter===s?'active':''}" data-filter="${s}" aria-pressed="${filter===s}">${s}<span>${jobs.filter(j=>s==='All'||j.status===s).length}</span></button>`).join('')}</div></div><div id="job-results">${jobRows(filteredJobs())}</div>`}
function field(label,id,value='',placeholder='',type='text',extra=''){return `<div class="field" id="field-${id}"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${extra} aria-describedby="error-${id}"><span class="field-error" id="error-${id}"></span></div>`}
function draftSeed(){return {customer:1,title:'',date:today,time:'09:00',window:'09:00–11:00',priority:'Normal',notes:'',items:[],scheduled:true}}
function itemRows(items,editable=true,context='job'){return items.map((x,i)=>`<div class="line-item"><div><strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${money(x.price)} / ${esc(x.unit)}</small>${editable?`<br><button class="remove" data-action="remove-line" data-index="${i}" data-context="${context}" aria-label="Remove ${esc(x.name)}">Remove</button>`:''}</div>${editable?`<div class="stepper" aria-label="Quantity for ${esc(x.name)}"><button data-action="quantity" data-index="${i}" data-delta="-1" data-context="${context}" aria-label="Decrease ${esc(x.name)} quantity" ${x.qty<=1?'disabled':''}>−</button><span aria-live="polite">${x.qty}</span><button data-action="quantity" data-index="${i}" data-delta="1" data-context="${context}" aria-label="Increase ${esc(x.name)} quantity">+</button></div>`:`<small>${x.qty} ${esc(x.unit)}</small>`}<span class="amount">${money(x.price*x.qty)}</span></div>`).join('')}
function newJob(){if(!draft)draft=draftSeed();const c=customer(draft);return `<div class="form-page">${heading('Make work happen','Create a job','Customer, service, and a time. You’re ready to go.',linkButton('Cancel','jobs'))}<div class="form-layout"><div class="form-main"><section class="card"><div class="card-head"><h2><span class="section-number">1</span>Customer & job</h2><button class="text-link" data-action="new-customer" data-context="draft">${icon('plus')}New customer</button></div><div class="card-body"><div class="field-grid"><div class="field wide"><label for="customer-search">Customer</label><input id="customer-search" list="customer-options" value="${esc(c.name)}" placeholder="Search by customer name" autocomplete="off" aria-describedby="error-customer-search"><datalist id="customer-options">${customers.map(x=>`<option value="${esc(x.name)}"></option>`).join('')}</datalist><span id="error-customer-search" class="field-error"></span><div class="customer-choice"><span class="avatar">${esc(c.initials)}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.address)}</p></div>${icon('check')}</div></div><div class="field wide" id="field-job-title"><label for="job-title">Job title <span class="optional">Required</span></label><input id="job-title" data-draft="title" value="${esc(draft.title)}" placeholder="e.g. Water heater repair" maxlength="160" aria-describedby="error-job-title"><span class="field-error" id="error-job-title"></span><div class="quick-picks">${['Diagnostic visit','Annual maintenance','Emergency repair'].map(x=>`<button data-action="quick-title" data-title="${x}">${x}</button>`).join('')}</div></div></div></div></section><section class="card"><div class="card-head"><h2><span class="section-number">2</span>Services & parts</h2><span class="muted small">${draft.items.length} items</span></div><div class="card-body">${draft.items.length?itemRows(draft.items,true,'draft'):`<div class="item-empty">${icon('box')}<h3>Build the work, as you go</h3><p>Add a saved service, part, or a custom item.</p></div>`}${button('Add items','open-picker',false,'plus','data-context="draft" style="width:100%;margin-top:12px"')}<p class="field-hint" style="margin-top:10px">You can also add items after creating the job.</p></div></section><section class="card"><div class="card-head"><h2><span class="section-number">3</span>When & where</h2></div><div class="card-body"><div class="radio-cards"><button class="${draft.scheduled?'selected':''}" data-action="schedule-choice" data-value="yes" aria-pressed="${draft.scheduled}"><span class="radio-dot"></span>Schedule a visit</button><button class="${!draft.scheduled?'selected':''}" data-action="schedule-choice" data-value="no" aria-pressed="${!draft.scheduled}"><span class="radio-dot"></span>Schedule later</button></div>${draft.scheduled?`<div class="field-grid">${field('Date','job-date',draft.date,'','date','data-draft="date"')}${field('Arrival time','job-time',draft.time,'','time','data-draft="time"')}</div><p class="field-hint" style="margin-top:10px">Workspace local time · No automatic time-zone conversion.</p>`:'<p class="field-hint">Save as a draft. Set the visit date when you’re ready.</p>'}<div class="field" style="margin-top:20px"><label for="job-notes">Internal notes <span class="optional">Optional</span></label><textarea id="job-notes" data-draft="notes" placeholder="Access instructions, tools to bring, anything helpful…">${esc(draft.notes)}</textarea><span class="field-hint">Only your team can see these notes.</span></div></div></section></div><aside class="summary card"><div class="card-head"><h2>Job summary</h2>${badge(draft.scheduled?'Scheduled':'Draft')}</div><div class="card-body"><div class="summary-line"><span>Customer</span><strong>${esc(c.name)}</strong></div><div class="summary-line"><span>Visit</span><strong>${draft.scheduled?dateLabel(draft.date):'Schedule later'}</strong></div><div class="summary-line"><span>Items</span><strong>${draft.items.length}</strong></div><div class="summary-line"><span>Subtotal</span><strong>${money(total(draft))}</strong></div><div class="summary-line"><span>Tax</span><strong>${money(0)}</strong></div><div class="summary-total"><span>Total <small style="display:inline;font-weight:400">${currency}</small></span><strong>${money(total(draft))}</strong></div>${button('Create job','save-job',true,'arrow')}<small>No invoice is issued yet.</small><div class="summary-meta">${icon('shield')}Review the work with your customer before issuing an invoice.</div></div></aside></div><div class="form-actions-mobile"><div><small>Total · ${currency}</small><strong>${money(total(draft))}</strong></div>${button('Create job','save-job',true,'arrow')}</div></div>`}
function jobDetail(){const j=current(),c=customer(j),done=j.status==='Completed',next=done?(j.invoice?linkButton('View invoice',`invoice/${j.id}`,true,'file'):button('Create invoice','create-invoice',true,'file')):j.status==='In progress'?button('Complete job','complete-job',true,'check'):j.status==='Draft'?button('Schedule visit','schedule-job',true,'calendar'):button('Start job','start-job',true,'arrow');const stage=done?(j.invoice==='Paid'?4:3):j.status==='In progress'?2:1;
 return `<div class="detail-page"><a class="back-link" href="#jobs">${icon('left')}Back to jobs</a>${heading(`#J-${j.id}`,esc(j.title),`${esc(c.name)} · ${esc(c.address)}`,next)}<div class="progress-track" aria-label="Job progress">${['Created','Scheduled','In progress','Completed','Paid'].map((s,i)=>`<span class="progress-step ${i<stage?'done':i===stage?'current':''}"><i>${i<stage?'✓':i+1}</i>${s}${i<4?'<span class="connector"></span>':''}</span>`).join('')}</div><div class="detail-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Visit details</h2>${badge(j.status)}</div><div class="card-body"><div class="detail-meta"><div><small>Date & arrival</small><strong>${dateLabel(j.date)} · ${j.time||'Not set'}</strong></div><div><small>Assigned to</small><strong>${esc(j.staff)}</strong></div><div><small>Priority</small><strong>${esc(j.priority)}</strong></div></div><p class="note">${esc(j.notes||'No internal notes added.')}</p>${!done?'<button class="text-link" data-action="schedule-job">Change visit date</button>':''}</div></section><section class="card"><div class="card-head"><div><h2>Services & parts</h2><p>${j.items.length} items · ${done?'Final work summary':'Add what the job needs'}</p></div>${!done?button('Add items','open-picker',false,'plus','data-context="job"'):''}</div><div class="card-body">${j.items.length?itemRows(j.items,!done):'<p class="muted">No items yet. Add a service to get started.</p>'}<div class="summary-total"><span>Job total <small class="muted">${currency}</small></span><strong>${money(total(j))}</strong></div></div></section><section class="card"><div class="card-head"><h2>Activity</h2></div><div class="card-body"><div class="activity-row"><i class="activity-dot"></i><div>${done?'Work completed':j.status==='In progress'?'Work started':'Job created'}<p>${esc(j.staff)} · ${dateLabel(j.date||today)}</p></div></div>${j.estimate?`<div class="activity-row"><i class="activity-dot"></i><div>Estimate ${j.estimate.toLowerCase()}<p>Revision 1 · ${money(total(j))}</p></div></div>`:''}</div></section></div><aside class="stack"><section class="card"><div class="card-head"><h2>Customer</h2></div><div class="card-body"><div class="customer-info"><span class="avatar">${esc(c.initials)}</span><div><h3>${esc(c.name)}</h3><p>Residential customer</p></div></div><div class="address-line">${icon('location')}${esc(c.address)}</div><div class="address-line">${icon('mail')}${esc(c.email)}</div><a href="#customers" class="text-link" style="margin-top:10px">Customer details ${icon('arrow')}</a></div></section><section class="card"><div class="card-head"><h2>Estimates & invoices</h2></div><div class="card-body">${j.estimate?`<a class="document-link" href="#estimate/${j.id}"><span><b>#EST-${j.id}</b><small>${money(total(j))} · Revision 1</small></span>${badge(j.estimate)}</a>`:button('Create estimate','create-estimate',false,'file','style="width:100%"')}${j.invoice?`<a class="document-link" href="#invoice/${j.id}"><span><b>#INV-${j.id}</b><small>${money(balance(j))} remaining</small></span>${badge(j.invoice)}</a>`:`<p class="field-hint" style="margin-top:15px">${done?'Ready to create an invoice.':'Complete the work to create an invoice.'}</p>`}</div></section></aside></div></div>`;
}
function documentPaper(j,type){const c=customer(j);return `<section class="card document-paper"><div class="document-title"><div><div class="brand"><span class="brand-mark">s</span>Everyday Services</div><small>Good work. Clear pricing.</small></div><div><h2>${type==='estimate'?'Estimate':'Invoice'}</h2><small>#${type==='estimate'?'EST':'INV'}-${j.id} · ${currency}</small></div></div><div class="document-parties"><div><small>PREPARED FOR</small><strong>${esc(c.name)}</strong><p>${esc(c.address)}</p><p>${esc(c.email)}</p></div><div><small>${type==='estimate'?'VALID UNTIL':'DUE DATE'}</small><strong>6 Oct 2026</strong><p>Issued 22 Sep 2026</p></div></div><table class="invoice-lines"><thead><tr><th>Description</th><th>Qty</th><th class="unit-column">Rate</th><th>Amount</th></tr></thead><tbody>${j.items.map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.type)} · ${esc(x.unit)}</small></td><td>${x.qty}</td><td class="unit-column">${money(x.price)}</td><td>${money(x.price*x.qty)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><div class="summary-line"><span>Subtotal</span><strong>${money(total(j))}</strong></div><div class="summary-line"><span>Tax</span><strong>${money(0)}</strong></div><div class="summary-total"><span>Total · ${currency}</span><strong>${money(total(j))}</strong></div></div><p class="note">${type==='estimate'?'Please review the services and prices before approving. Additional work will be agreed separately.':'Thank you for choosing Everyday Services. Your payment history appears alongside this invoice.'}</p></section>`}
function financialDetail(type){const j=current(),isEstimate=type==='estimate',status=isEstimate?j.estimate:j.invoice;return `<div class="detail-page"><a class="back-link" href="#job/${j.id}">${icon('left')}Back to ${esc(j.title)}</a>${heading(isEstimate?'Clear scope. No surprises.':'From work done to paid.',`${isEstimate?'Estimate':'Invoice'} #${isEstimate?'EST':'INV'}-${j.id}`,`${esc(customer(j).name)} · ${currency}`,isEstimate?status==='Draft'?button('Prepare to send','send-estimate',true,'arrow'):status==='Sent'?linkButton('Preview customer view',`approval/${j.id}`,true,'file'):linkButton('Continue job',`job/${j.id}`,true,'arrow'):status==='Draft'?button('Issue invoice','issue-invoice',true,'arrow'):balance(j)>0?button('Record payment','open-payment',true,'money'):badge('Paid'))}${status==='Approved'?'<div class="info-banner">'+icon('check')+'<div><strong>Your customer approved this estimate.</strong><p>Continue from the job page when you are ready.</p></div></div>':''}${status==='Paid'?`<div class="info-banner">${icon('check')}Paid in full. ${money(total(j))} received. No balance remaining.</div>`:''}<div class="detail-grid">${documentPaper(j,type)}<aside class="stack"><section class="card"><div class="card-head"><h2>${isEstimate?'Approval':'Payment summary'}</h2>${badge(status)}</div><div class="card-body">${isEstimate?`<p class="muted small">${status==='Draft'?'Review the pricing, then prepare a customer approval link.':status==='Sent'?'Waiting for your customer’s decision.':'The agreed scope is saved with this estimate.'}</p><div class="summary-total"><span>Estimate total</span><strong>${money(total(j))}</strong></div>${status==='Sent'?linkButton('Preview approval page',`approval/${j.id}`,false,'arrow'):''}`:`<div class="summary-line"><span>Invoice total</span><strong>${money(total(j))}</strong></div><div class="summary-line"><span>Payments received</span><strong>${money(paid(j))}</strong></div><div class="summary-total"><span>Balance due</span><strong>${money(balance(j))}</strong></div><p class="field-hint" style="margin-top:15px">${status==='Draft'?'Issue the invoice before recording a payment.':'Manual records only. No payment is charged here.'}</p>`}</div></section>${!isEstimate?`<section class="card"><div class="card-head"><h2>Payment history</h2><span class="muted small">${j.payments.length} records</span></div><div class="card-body">${j.payments.length?j.payments.map(p=>`<div class="payment-row"><div><strong>${esc(p.method)}</strong><p>${dateLabel(p.date)} · ${esc(p.ref||'No reference')}</p></div><b>${money(p.amount)}</b></div>`).join(''):'<p class="muted small">No payments recorded yet.</p>'}</div></section>`:''}<div class="summary-meta">${icon('shield')}Design preview. Sending, approval, and payments are simulated in this tab.</div></aside></div></div>`}
function financialList(type){const rows=jobs.filter(j=>type==='estimates'?j.estimate:j.invoice);return heading(type==='estimates'?'Your sales pipeline':'Your money, in view',type==='estimates'?'Estimates':'Invoices',type==='estimates'?'Keep approvals moving without losing sight of the work.':'See what is paid, what is open, and what needs a follow-up.',linkButton('View jobs','jobs',false,'jobs'))+jobRows(rows,type)}
function customersPage(){return heading('Good service starts here','Customers','Contact details and the next job, together.',button('New customer','new-customer',true,'plus','data-context="customers"'))+`<div class="customer-grid">${customers.map(c=>`<article class="card customer-tile"><span class="avatar">${esc(c.initials)}</span><h3>${esc(c.name)}</h3><p>${esc(c.address)}</p><p>${esc(c.email)}</p><p>${jobs.filter(j=>j.customer===c.id).length} jobs · ${esc(c.phone)}</p>${button('Create job','customer-job',false,'plus',`data-id="${c.id}"`)}</article>`).join('')}</div>`}
function schedulePage(){const days=['21','22','23','24','25','26','27'],labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const rows=jobs.filter(j=>j.date===scheduleDay).sort((a,b)=>a.time.localeCompare(b.time));return heading('Plan a little. Do a lot.','Schedule','21–27 September · All seven days, in workspace local time.',linkButton('New job','new-job',true,'plus'))+`<div class="calendar-strip">${days.map((d,i)=>`<button class="calendar-day ${scheduleDay==='2026-09-'+d?'active':''}" data-action="schedule-day" data-date="2026-09-${d}" aria-pressed="${scheduleDay==='2026-09-'+d}">${labels[i]}<b>${d}</b>${jobs.some(j=>j.date==='2026-09-'+d)?'<i></i>':''}</button>`).join('')}</div><h2 class="schedule-title">${labels[days.indexOf(scheduleDay.slice(-2))]} ${dateLabel(scheduleDay)} <span class="muted small">· ${rows.length} visits</span></h2><section class="card">${rows.length?rows.map(agendaRow).join(''):`<div class="empty-state">${icon('calendar')}<h2>A little breathing room</h2><p>No visits scheduled for this day.</p>${linkButton('Schedule a job','new-job',true,'plus')}</div>`}</section>`}
function reportsPage(){const received=jobs.reduce((s,j)=>s+paid(j),0),open=jobs.filter(j=>j.invoice&&j.invoice!=='Draft').reduce((s,j)=>s+balance(j),0),completed=jobs.filter(j=>j.status==='Completed').length;return heading('See the bigger picture','Reports','September 2026 · Sample workspace · All amounts in '+currency,button('Export summary','export-report',false,'download'))+`<div class="stats">${stat('Collected',money(received),'Payments received this month','money',true)}${stat('Still to collect',money(open),'Issued invoice balances','file')}${stat('Completed jobs',completed,'Completed service visits','check')}${stat('Customers',customers.length,'Active customer accounts','users')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Payments received</h2><p>Monthly collected amount · ${currency}</p></div><span class="badge">Sample history</span></div><div class="card-body"><div class="chart" role="img" aria-label="Sample historical payments: April 320, May 410, June 280, July 520, August 460; September ${received} ${currency}">${[320,410,280,520,460,received].map((v,i)=>`<div class="bar-group"><small>${money(v)}</small><div class="bar ${i===5?'current':''}" style="height:${Math.max(3,v/Math.max(520,received)*130)}px"></div><span>${['Apr','May','Jun','Jul','Aug','Sep'][i]}</span></div>`).join('')}</div><p class="field-hint" style="margin-top:18px">April–August are illustrative history. September updates as you record demo payments.</p></div></section><section class="card"><div class="card-head"><h2>Work by status</h2></div><div class="card-body">${['Draft','Scheduled','In progress','Completed'].map(s=>{const n=jobs.filter(j=>j.status===s).length;return `<div class="report-row"><span>${s}</span><div class="progress"><i style="width:${n/jobs.length*100}%"></i></div><strong>${n} jobs</strong></div>`}).join('')}</div></section></div><div class="welcome-note">${icon('shield')}Collected means actual recorded payments. Unpaid balances exclude draft and paid invoices.</div>`}
function catalogPage(){return heading('Your reusable price book','Services & parts','Spend less time entering the same work.',linkButton('Create a job','new-job',true,'plus'))+`<section class="card"><div class="card-head"><h2>Saved items</h2><span class="muted small">${catalog.length} items · ${currency}</span></div><div class="card-body"><div class="catalog-list" style="margin:0">${catalog.map(x=>`<div class="catalog-choice"><span class="item-symbol">${icon(x.icon)}</span><div class="info"><strong>${esc(x.name)}</strong><small>${x.type} · per ${x.unit}</small></div><span class="price">${money(x.price)}</span>${button('Use in job','catalog-job',false,'plus',`data-id="${x.id}"`)}</div>`).join('')}</div></div></section>`}
function settingsPage(){return heading('Make it yours','Preferences','Explore the same screens with your preferred display format.')+`<section class="card settings-panel"><div class="card-head"><h2>Regional display</h2><span class="badge">Preview only</span></div><div class="card-body"><p class="muted small" style="margin-bottom:20px">The live product should use each workspace’s currency, time zone, and address format consistently.</p><div class="field-grid"><div class="field"><label for="currency">Display currency</label><select id="currency"><option value="USD" ${currency==='USD'?'selected':''}>USD · US dollar</option><option value="INR" ${currency==='INR'?'selected':''}>INR · Indian rupee</option><option value="GBP" ${currency==='GBP'?'selected':''}>GBP · British pound</option><option value="EUR" ${currency==='EUR'?'selected':''}>EUR · Euro</option><option value="AUD" ${currency==='AUD'?'selected':''}>AUD · Australian dollar</option></select></div><div class="field"><label for="locale">Number and date format</label><select id="locale"><option value="en-US" ${locale==='en-US'?'selected':''}>English · United States</option><option value="en-GB" ${locale==='en-GB'?'selected':''}>English · United Kingdom</option><option value="en-IN" ${locale==='en-IN'?'selected':''}>English · India</option><option value="de-DE" ${locale==='de-DE'?'selected':''}>German · Germany</option></select></div></div><div class="info-banner warning" style="margin-top:20px">${icon('money')}Formatting demo only. Changing currency relabels sample amounts; it does not convert money or change your live business settings.</div>${button('Apply display preferences','apply-settings',true,'check')}</div></section>`}
function publicApproval(){const j=current();return `<div class="public-preview">${heading('Customer view · Design preview','A clear price. Your decision.',esc(j.title),linkButton('Back to estimate',`estimate/${j.id}`,false,'left'))}${documentPaper(j,'estimate')}<section class="card" style="margin-top:20px"><div class="card-head"><h2>${j.estimate==='Approved'?'Approval recorded':j.estimate==='Declined'?'Response recorded':'Ready to go ahead?'}</h2></div><div class="card-body">${['Approved','Declined'].includes(j.estimate)?`<div class="info-banner">${icon('check')}This demo estimate has been ${j.estimate.toLowerCase()}.</div>`:`<p class="muted small" style="margin-bottom:18px">Review the scope and total above. This preview does not create a real agreement.</p><div class="field-grid">${field('Your name','approval-name','','Full name')}${field('Email','approval-email','','you@example.com','email')}</div><div class="actions" style="justify-content:flex-end;margin-top:20px">${button('Decline','decline-demo')}${button('Approve estimate','approve-demo',true,'check')}</div>`}</div></section></div>`}
function render(){shell();main.innerHTML=({overview:dashboard,jobs:jobsPage,'new-job':newJob,job:jobDetail,estimates:()=>financialList('estimates'),invoices:()=>financialList('invoices'),estimate:()=>financialDetail('estimate'),invoice:()=>financialDetail('invoice'),customers:customersPage,schedule:schedulePage,reports:reportsPage,catalog:catalogPage,settings:settingsPage,approval:publicApproval}[route]||dashboard)();}
function navigate(hash){location.hash=hash}
function readRoute(){const [next,id]=location.hash.slice(1).split('/');route=next||'overview';if(id&&jobs.some(j=>j.id===Number(id)))currentId=Number(id);filter='All';query='';closeMenu();render();window.scrollTo(0,0);main.focus({preventScroll:true})}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500)}
function openDialog(title,subtitle,content,footer=''){lastFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${content}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;dialog.showModal();}
function closeDialog(){dialog.close();lastFocus?.focus?.()}
function syncSidebar(){const sidebar=document.querySelector('#sidebar');sidebar.inert=matchMedia('(max-width:900px)').matches&&!sidebar.classList.contains('open')}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('.scrim').hidden=true;document.querySelectorAll('[data-action="menu"]').forEach(b=>b.setAttribute('aria-expanded','false'));syncSidebar()}
function pickerRows(){const rows=catalog.filter(x=>(pickerFilter==='All'||x.type===pickerFilter)&&`${x.name} ${x.description}`.toLowerCase().includes(pickerQuery.toLowerCase()));return rows.length?rows.map(x=>`<div class="catalog-choice ${pickerSelection[x.id]?'selected':''}"><span class="item-symbol">${icon(x.icon)}</span><div class="info"><strong>${x.name}</strong><small>${x.type} · per ${x.unit}</small></div><span class="price">${money(x.price)}</span><button class="button small ${pickerSelection[x.id]?'soft':''}" data-action="pick-item" data-id="${x.id}" aria-pressed="${!!pickerSelection[x.id]}" aria-label="${pickerSelection[x.id]?'Remove':'Select'} ${x.name}">${icon(pickerSelection[x.id]?'check':'plus')}</button></div>`).join(''):'<div class="empty-state"><h3>No matching items</h3><p>Try another search or add a custom item below.</p></div>'}
function picker(){openDialog('Add services & parts','Pick several items. Adjust quantities on the job.',`<label class="search" style="max-width:none">${icon('search')}<input aria-label="Search saved items" data-input="picker-search" placeholder="Search your price book…"></label><div class="catalog-tabs">${['All','Service','Part','Labor'].map(s=>`<button class="chip ${pickerFilter===s?'active':''}" data-picker-filter="${s}">${s==='All'?'All items':s==='Labor'?'Labor':s+'s'}</button>`).join('')}</div><div class="catalog-list" id="picker-results">${pickerRows()}</div><div class="custom-item"><h3>Something different?</h3><p class="muted small" style="margin:5px 0 12px">Add a custom item just for this job.</p><div class="field-grid">${field('Item name','custom-name','','e.g. Replacement valve')}${field('Unit price · '+currency,'custom-price','','0.00','number','min="0" step="0.01"')}</div>${button('Add custom item','add-custom',false,'plus','style="margin-top:12px"')}</div>`,`<p id="picker-summary"><strong>0</strong> items selected</p>${button('Add to job','commit-picker',true,'plus','id="commit-picker" disabled')}`)}
function updatePicker(){document.querySelector('#picker-results').innerHTML=pickerRows();const selected=Object.values(pickerSelection);document.querySelector('#picker-summary').innerHTML=`<strong>${selected.length}</strong> selected · ${money(selected.reduce((s,x)=>s+x.price,0))}`;document.querySelector('#commit-picker').disabled=selected.length===0}
function error(id,message){const input=document.getElementById(id);const field=input?.closest('.field')||input?.parentElement;field?.classList.add('has-error');input?.setAttribute('aria-invalid','true');const target=document.getElementById('error-'+id);if(target)target.textContent=message;}
function clearErrors(){document.querySelectorAll('.has-error').forEach(e=>e.classList.remove('has-error'));document.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));document.querySelectorAll('.field-error').forEach(e=>e.textContent='')}
function saveJob(){clearErrors();let valid=true;if(!draft.title.trim()){error('job-title','Enter a short job title.');valid=false}const typed=document.querySelector('#customer-search').value.trim();const selected=customers.find(c=>c.name.toLowerCase()===typed.toLowerCase());if(!selected){error('customer-search','Choose an existing customer or add a new one.');valid=false}else draft.customer=selected.id;if(draft.scheduled&&!draft.date){error('job-date','Choose a visit date.');valid=false}if(draft.scheduled&&!draft.time){error('job-time','Choose an arrival time.');valid=false}if(!valid){document.querySelector('[aria-invalid="true"]')?.focus();return}const id=Math.max(...jobs.map(j=>j.id))+1;jobs.unshift({...structuredClone(draft),id,title:draft.title.trim(),status:draft.scheduled?'Scheduled':'Draft',date:draft.scheduled?draft.date:'',time:draft.scheduled?draft.time:'',window:draft.scheduled?draft.time+' arrival':'',staff:'You',estimate:null,invoice:null,payments:[]});draft=null;currentId=id;navigate('job/'+id);toast('Job created. Everything you need is on this page.')}
function paymentDialog(){const j=current();openDialog('Record a payment',`Invoice #INV-${j.id} · Balance ${money(balance(j))}`,`<div class="info-banner">${icon('money')}Record money already received. This does not charge the customer.</div><div class="field-grid">${field('Amount · '+currency,'payment-amount',balance(j).toFixed(2),'','number','min="0.01" step="0.01"')}<div class="field"><label for="payment-method">Payment method</label><select id="payment-method"><option value="">Choose a method</option><option>Cash</option><option>Card</option><option>Bank transfer</option><option>Check</option><option>Other</option></select><span class="field-error" id="error-payment-method"></span></div>${field('Received on','payment-date',today,'','date')}${field('Reference · optional','payment-reference','','Bank or receipt reference')}</div><p class="field-hint" style="margin-top:15px">Partial payments are welcome. A receipt record will appear on the invoice.</p>`,`${button('Cancel','close-dialog')}${button('Record payment','save-payment',true,'check')}`)}
function newCustomerDialog(){openDialog('Add a customer','Only the details you need to start the work.',`<div class="field-grid">${field('Full name','customer-name','','Customer name')}${field('Phone · optional','customer-phone','','Include country code','tel')}${field('Email · optional','customer-email','','customer@example.com','email')}${field('City / locality','customer-city','','Any city or locality')}<div class="field wide"><label for="customer-address">Service address <span class="optional">Optional</span></label><textarea id="customer-address" placeholder="Use the customer’s local address format"></textarea></div></div>`,`${button('Cancel','close-dialog')}${button('Save customer','save-customer',true,'check')}`)}
document.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('aria-invalid')){t.removeAttribute('aria-invalid');t.closest('.field')?.classList.remove('has-error');const message=document.getElementById('error-'+t.id);if(message)message.textContent=''}if(t.dataset.draft&&draft)draft[t.dataset.draft]=t.value;if(t.dataset.input==='job-search'){query=t.value;document.querySelector('#job-results').innerHTML=jobRows(filteredJobs())}if(t.dataset.input==='picker-search'){pickerQuery=t.value;updatePicker()}});
document.addEventListener('change',e=>{if(e.target.id==='customer-search'&&draft){const found=customers.find(c=>c.name===e.target.value);if(found){draft.customer=found.id;render()}}});
document.addEventListener('click',e=>{
 if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView();return}
 const t=e.target.closest('[data-action],[data-nav],[data-filter],[data-picker-filter]');if(!t)return;
 if(t.dataset.nav){navigate(t.dataset.nav);return}
 if(t.dataset.filter){filter=t.dataset.filter;render();return}
 if(t.dataset.pickerFilter){pickerFilter=t.dataset.pickerFilter;dialog.querySelectorAll('[data-picker-filter]').forEach(b=>b.classList.toggle('active',b.dataset.pickerFilter===pickerFilter));updatePicker();return}
 const j=current();switch(t.dataset.action){
 case 'menu':{const open=!document.querySelector('#sidebar').classList.contains('open');document.querySelector('#sidebar').classList.toggle('open',open);document.querySelector('.scrim').hidden=!open;document.querySelectorAll('[data-action="menu"]').forEach(b=>b.setAttribute('aria-expanded',String(open)));syncSidebar();if(open)document.querySelector('#sidebar .brand').focus();break}
 case 'close-menu':closeMenu();break;
 case 'close-dialog':closeDialog();break;
 case 'reset':jobs=seedJobs();customers=structuredClone(initialCustomers);draft=null;currentId=1042;currency='USD';locale='en-US';if(route!=='overview')navigate('overview');else render();toast('Demo restored to its starting point.');break;
 case 'clear-filter':query='';filter='All';render();break;
 case 'quick-title':draft.title=t.dataset.title;document.querySelector('#job-title').value=draft.title;break;
 case 'schedule-choice':draft.scheduled=t.dataset.value==='yes';render();break;
 case 'open-picker':pickerContext=t.dataset.context||'job';pickerSelection={};pickerFilter='All';pickerQuery='';picker();break;
 case 'pick-item':if(pickerSelection[t.dataset.id])delete pickerSelection[t.dataset.id];else pickerSelection[t.dataset.id]={...catalog.find(x=>x.id===t.dataset.id),qty:1};updatePicker();break;
 case 'add-custom':{clearErrors();const name=document.querySelector('#custom-name').value.trim(),raw=document.querySelector('#custom-price').value,price=Number(raw);if(!name){error('custom-name','Enter an item name.');break}if(raw===''||!Number.isFinite(price)||price<0){error('custom-price','Enter a price of zero or more.');break}const id='custom-'+Date.now();pickerSelection[id]={id,name,type:'Service',unit:'each',price:Math.round(price*100)/100,qty:1};updatePicker();document.querySelector('#custom-name').value='';document.querySelector('#custom-price').value='';toast('Custom item selected. Use Add to job to finish.');break}
 case 'commit-picker':{const target=pickerContext==='draft'?draft:j;for(const x of Object.values(pickerSelection)){const existing=target.items.find(i=>i.id===x.id);if(existing)existing.qty+=x.qty;else target.items.push(x)}closeDialog();render();toast('Items added. Quantities and totals are ready to review.');break}
 case 'quantity':{const target=t.dataset.context==='draft'?draft:j;target.items[Number(t.dataset.index)].qty=Math.max(1,target.items[Number(t.dataset.index)].qty+Number(t.dataset.delta));render();break}
 case 'remove-line':{const target=t.dataset.context==='draft'?draft:j;target.items.splice(Number(t.dataset.index),1);render();toast('Item removed from this job.');break}
 case 'save-job':saveJob();break;
 case 'start-job':j.status='In progress';render();toast('Job started. Add any extra work as you go.');break;
 case 'complete-job':openDialog('Complete this job?',`${esc(j.title)} · ${money(total(j))}`,`<p class="muted">Review the services and total before completing. The next step is a draft invoice.</p><div class="summary-total"><span>${j.items.length} items · ${currency}</span><strong>${money(total(j))}</strong></div>`,`${button('Keep working','close-dialog')}${button('Complete & draft invoice','confirm-complete',true,'check')}`);break;
 case 'confirm-complete':if(!j.items.length){toast('Add at least one item before creating an invoice.');break}j.status='Completed';j.invoice='Draft';closeDialog();navigate('invoice/'+j.id);toast('Work completed. Review the draft invoice before issuing.');break;
 case 'create-invoice':if(j.status==='Completed'&&j.items.length){j.invoice=j.invoice||'Draft';navigate('invoice/'+j.id)}else toast('Complete the work and add an item first.');break;
 case 'create-estimate':if(!j.items.length){toast('Add at least one service or part to create an estimate.');break}j.estimate='Draft';navigate('estimate/'+j.id);break;
 case 'send-estimate':openDialog('Prepare customer approval',`Estimate #EST-${j.id}`,`<p class="muted small">The production flow would send a secure approval link to:</p><div class="customer-choice"><span class="avatar">${customer(j).initials}</span><div><strong>${esc(customer(j).name)}</strong><p>${esc(customer(j).email)}</p></div></div><div class="info-banner" style="margin-top:18px">${icon('shield')}This design preview does not send email. The next screen simulates a sent estimate.</div>`,`${button('Back','close-dialog')}${button('Simulate sending','confirm-send',true,'arrow')}`);break;
 case 'confirm-send':j.estimate='Sent';closeDialog();render();toast('Demo estimate marked sent. Preview the customer approval page.');break;
 case 'approve-demo':case 'decline-demo':{clearErrors();const name=document.querySelector('#approval-name').value.trim(),email=document.querySelector('#approval-email').value.trim();let valid=true;if(!name){error('approval-name','Enter your name.');valid=false}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){error('approval-email','Enter a valid email address.');valid=false}if(!valid){document.querySelector('[aria-invalid="true"]')?.focus();break}j.estimate=t.dataset.action==='approve-demo'?'Approved':'Declined';render();toast('Demo response recorded. No agreement was signed.');break}
 case 'issue-invoice':j.invoice='Issued';render();toast('Demo invoice issued. You can now record money received.');break;
 case 'open-payment':paymentDialog();break;
 case 'save-payment':{clearErrors();const amount=Number(document.querySelector('#payment-amount').value),method=document.querySelector('#payment-method').value,date=document.querySelector('#payment-date').value;let valid=true;if(!Number.isFinite(amount)||amount<=0||amount>balance(j)){error('payment-amount',`Enter an amount from ${money(.01)} to ${money(balance(j))}.`);valid=false}if(!method){error('payment-method','Choose how the customer paid.');valid=false}if(!date||date>today){error('payment-date','Choose a date on or before the demo date, 22 Sep 2026.');valid=false}if(!valid){dialog.querySelector('[aria-invalid="true"]')?.focus();break}j.payments.push({amount:Math.round(amount*100)/100,method,date,ref:document.querySelector('#payment-reference').value.trim()});j.invoice=balance(j)<.005?'Paid':'Issued';closeDialog();render();toast('Payment recorded in the demo. No money was charged.');break}
 case 'new-customer':customerContext=t.dataset.context||'customers';newCustomerDialog();break;
 case 'save-customer':{clearErrors();const name=document.querySelector('#customer-name').value.trim(),email=document.querySelector('#customer-email').value.trim();if(!name){error('customer-name','Enter the customer’s name.');break}if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){error('customer-email','Enter a valid email or leave it blank.');break}const id=Math.max(...customers.map(c=>c.id))+1;customers.push({id,name,email,phone:document.querySelector('#customer-phone').value.trim(),address:[document.querySelector('#customer-address').value.trim(),document.querySelector('#customer-city').value.trim()].filter(Boolean).join(', ')||'Address to be arranged',initials:name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()});if(customerContext==='draft'&&draft)draft.customer=id;closeDialog();render();toast('Customer saved. Continue with the job.');break}
 case 'customer-job':draft=draftSeed();draft.customer=Number(t.dataset.id);navigate('new-job');break;
 case 'catalog-job':draft=draftSeed();draft.items=[line(t.dataset.id)];draft.title=draft.items[0].name;navigate('new-job');break;
 case 'schedule-day':scheduleDay=t.dataset.date;render();break;
 case 'schedule-job':openDialog('Schedule this visit','Choose a date and a clear arrival time.',`<div class="field-grid">${field('Visit date','visit-date',j.date||today,'','date')}${field('Arrival time','visit-time',j.time||'09:00','','time')}</div>`,`${button('Cancel','close-dialog')}${button('Save visit','save-visit',true,'check')}`);break;
 case 'save-visit':{clearErrors();const date=document.querySelector('#visit-date').value,time=document.querySelector('#visit-time').value;if(!date){error('visit-date','Choose a visit date.');break}if(!time){error('visit-time','Choose an arrival time.');break}j.date=date;j.time=time;j.window=time+' arrival';if(j.status==='Draft')j.status='Scheduled';closeDialog();render();toast('Visit updated in workspace local time.');break}
 case 'apply-settings':currency=document.querySelector('#currency').value;locale=document.querySelector('#locale').value;render();toast('Preview formatting updated. Sample values were not converted.');break;
 case 'export-report':{const data=[['Metric','Value','Currency'],['Payments received',jobs.reduce((s,x)=>s+paid(x),0),currency],['Issued unpaid balance',jobs.filter(x=>x.invoice&&x.invoice!=='Draft').reduce((s,x)=>s+balance(x),0),currency],['Completed jobs',jobs.filter(x=>x.status==='Completed').length,''],['Customers',customers.length,'']];const blob=new Blob([data.map(row=>row.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='servicedesk-demo-summary.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample report downloaded.');break}
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
dialog.addEventListener('close',()=>lastFocus?.focus?.());
window.addEventListener('hashchange',readRoute);
window.addEventListener('resize',syncSidebar);
readRoute();
